/**
 * auto-session-name.ts
 *
 * Automatically gives each pi session a durable, chronologically-numbered
 * display name with a short LLM-generated summary label, e.g.:
 *   "07 - refactor auth token expiry"
 *
 * Behavior:
 *  - NN is assigned ONCE per session (0-based chronological index among the
 *    project's session .jsonl files at assignment time) and persisted as a
 *    `custom` entry on the session. Resuming an old conversation keeps its
 *    original NN forever; it is never recomputed.
 *  - The summary label is generated by a one-shot `pi --no-session -p ...`
 *    subprocess (uses your configured provider/auth/model) after the session
 *    has enough context: at least MIN_TURNS user prompts OR MIN_TOKENS
 *    cumulative total tokens burned on the active branch, whichever first.
 *  - Naming runs only in TUI mode (so `-p`/rpc/json runs don't spawn nested
 *    subprocesses). A `/auto-name` command triggers it on demand.
 *
 * Tune the constants below to taste.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Name after at least this many user prompts on the active branch. */
const MIN_TURNS = 5;

/** ...or after this many cumulative total tokens burned, whichever comes first.
 *  12000 is enough for the session's topic to be unambiguous, even in one
 *  long deep turn, without waiting too long on multi-turn sessions. */
const MIN_TOKENS = 12000;

/** Hard timeout for the summary subprocess. */
const SUMMARY_TIMEOUT_MS = 90_000;

/** Excerpt sizes used when building the summarizer prompt (chars). */
const MAX_USER_EXCERPT = 240;
const MAX_ASSISTANT_EXCERPT = 320;

/** Max user/assistant exchanges fed to the summarizer. */
const MAX_EXCHANGES_IN_PROMPT = 6;

/** Custom-entry type used to persist NN + named state on the session file. */
const IDX_TYPE = "auto-session-idx";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

interface StoredIdx {
	nn: number;
	named?: boolean;
	label?: string;
}

/** Extract plain text from a message's content (string or content blocks). */
function extractText(content: unknown): string {
	if (typeof content === "string") return content;
	if (!Array.isArray(content)) return "";
	const parts: string[] = [];
	for (const block of content) {
		if (block && typeof block === "object" && (block as { type?: string }).type === "text") {
			const text = (block as { text?: string }).text;
			if (typeof text === "string") parts.push(text);
		}
	}
	return parts.join("\n");
}

function clip(s: string, max: number): string {
	s = s.trim().replace(/\s+/g, " ");
	if (s.length <= max) return s;
	return s.slice(0, max - 1).trimEnd() + "…";
}

/** Find the latest persisted auto-session-idx entry, if any. */
function readStoredIdx(entries: { type: string; customType?: string; data?: unknown }[]): StoredIdx | undefined {
	for (let i = entries.length - 1; i >= 0; i--) {
		const e = entries[i];
		if (e.type === "custom" && e.customType === IDX_TYPE && e.data) {
			return e.data as StoredIdx;
		}
	}
	return undefined;
}

/** Compute the 0-based chronological index of `targetFile` among session files. */
function chronologicalIndex(sessionDir: string, targetFile: string): number {
	let fs: typeof import("node:fs");
	try {
		// pi extensions run on Node; require is available via createRequire.
		// eslint-disable-next-line @typescript-eslint/no-var-requires
		const { createRequire } = require("node:module");
		fs = createRequire(import.meta.url)("node:fs") as typeof import("node:fs");
	} catch {
		return 0;
	}
	let names: string[];
	try {
		names = fs
			.readdirSync(sessionDir)
			.filter((n) => n.endsWith(".jsonl"))
			.sort(); // timestamp prefix => chronological
	} catch {
		return 0;
	}
	const base = targetFile.split("/").pop() ?? targetFile;
	const idx = names.indexOf(base);
	return idx >= 0 ? idx : names.length; // fallback: next index
}

/** Clean the LLM response into a 4-5 word label. */
function cleanLabel(raw: string): string {
	let s = raw.trim();
	// first non-empty line
	s = s.split(/\r?\n/).find((l) => l.trim()) ?? s;
	s = s.trim();
	// strip wrapping quotes
	if ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'"))) {
		s = s.slice(1, -1).trim();
	}
	// drop a leading "label:" style prefix
	s = s.replace(/^[a-z_]+:\s*/i, "").trim();
	// strip leading/trailing punctuation
	s = s.replace(/^[\s\W]+|[\s\W]+$/g, "").trim();
	s = s.toLowerCase().replace(/\s+/g, " ");
	const words = s.split(" ").filter(Boolean).slice(0, 5);
	if (words.length === 0) return "session";
	return words.join(" ");
}

function formatName(nn: number, label: string): string {
	const num = nn < 100 ? String(nn).padStart(2, "0") : String(nn);
	return `${num} - ${label}`;
}

// ---------------------------------------------------------------------------
// Extension
// ---------------------------------------------------------------------------

export default function (pi: ExtensionAPI) {
	// Per-session re-entrancy guard for the naming subprocess.
	const namingInProgress = new Set<string>();

	// In-memory NN for the currently-bound session (also persisted on disk).
	let currentNn: number | undefined;

	function getCtxSessionFile(ctx: { sessionManager: { getSessionFile(): string | undefined } }): string | undefined {
		return ctx.sessionManager.getSessionFile();
	}

	/** Assign (or recall) NN for the current session. Runs on every session_start. */
	function ensureNn(ctx: {
		sessionManager: {
			getEntries(): { type: string; customType?: string; data?: unknown }[];
			getSessionDir(): string;
			getSessionFile(): string | undefined;
		};
	}): void {
		const entries = ctx.sessionManager.getEntries();
		const stored = readStoredIdx(entries);
		if (stored) {
			currentNn = stored.nn;
			return;
		}
		// No stored NN yet: assign once, persist.
		const file = ctx.sessionManager.getSessionFile();
		const dir = ctx.sessionManager.getSessionDir();
		if (!file) {
			currentNn = undefined;
			return;
		}
		const nn = chronologicalIndex(dir, file);
		currentNn = nn;
		pi.appendEntry(IDX_TYPE, { nn, named: false } satisfies StoredIdx);
	}

	/** Gather active-branch stats and a transcript excerpt. */
	function gatherBranch(ctx: {
		sessionManager: {
			getBranch(): { type: string; message?: unknown }[];
		};
	}): { userCount: number; totalTokens: number; transcript: string } {
		const branch = ctx.sessionManager.getBranch(); // leaf -> root
		const chrono = [...branch].reverse(); // root -> leaf

		let userCount = 0;
		let totalTokens = 0;
		const lines: string[] = [];
		let exchanges = 0;

		for (const entry of chrono) {
			if (entry.type !== "message" || !entry.message) continue;
			const msg = entry.message as {
				role: string;
				content: unknown;
				usage?: { totalTokens?: number };
			};
			if (msg.role === "user") {
				userCount++;
				if (exchanges < MAX_EXCHANGES_IN_PROMPT) {
					const t = clip(extractText(msg.content), MAX_USER_EXCERPT);
					lines.push(`User: ${t}`);
				}
			} else if (msg.role === "assistant") {
				if (msg.usage?.totalTokens) totalTokens += msg.usage.totalTokens;
				if (exchanges < MAX_EXCHANGES_IN_PROMPT) {
					const t = clip(extractText(msg.content), MAX_ASSISTANT_EXCERPT);
					if (t) {
						lines.push(`Assistant: ${t}`);
						exchanges++;
					}
				}
			}
		}

		return { userCount, totalTokens, transcript: lines.join("\n") };
	}

	/** Run the summarizer subprocess and return a cleaned 4-5 word label. */
	async function generateLabel(
		cwd: string,
		transcript: string,
		signal: AbortSignal,
	): Promise<string> {
		const prompt =
			`Below is a transcript of a coding agent session. Summarize what the session is ` +
			`about in 4 to 5 words as a concise label (lowercase, no punctuation, no leading ` +
			`articles like "the"/"a", no prefix). Reply with ONLY the label, nothing else.\n\n` +
			`Transcript:\n${transcript}`;

		const result = await pi.exec("pi", ["--no-session", "-p", prompt], {
			cwd,
			timeout: SUMMARY_TIMEOUT_MS,
			signal,
		});

		const out = (result.stdout || "").trim() || (result.stderr || "").trim();
		return cleanLabel(out);
	}

	/** Main naming routine. Returns true if it named the session. */
	async function tryName(
		ctx: {
			sessionManager: {
				getEntries(): { type: string; customType?: string; data?: unknown }[];
				getBranch(): { type: string; message?: unknown }[];
				getSessionFile(): string | undefined;
			};
			ui?: { notify(msg: string, level?: string): void };
			signal: AbortSignal;
			cwd: string;
		},
		opts: { force: boolean },
	): Promise<boolean> {
		const file = ctx.sessionManager.getSessionFile();
		if (!file) return false;
		if (currentNn === undefined) return false;

		const stored = readStoredIdx(ctx.sessionManager.getEntries());
		if (stored?.named && !opts.force) return false;
		if (namingInProgress.has(file)) return false;

		const { userCount, totalTokens, transcript } = gatherBranch(ctx);
		if (!opts.force) {
			if (userCount < MIN_TURNS && totalTokens < MIN_TOKENS) return false;
		}
		if (!transcript.trim()) return false;

		namingInProgress.add(file);
		try {
			const label = await generateLabel(ctx.cwd, transcript, ctx.signal);
			const name = formatName(currentNn, label);
			pi.setSessionName(name);
			pi.appendEntry(IDX_TYPE, {
				nn: currentNn,
				named: true,
				label,
			} satisfies StoredIdx);
			ctx.ui?.notify(`Session named: ${name}`, "info");
			return true;
		} catch (err) {
			const msg = err instanceof Error ? err.message : String(err);
			ctx.ui?.notify(`auto-session-name failed: ${msg}`, "error");
			return false;
		} finally {
			namingInProgress.delete(file);
		}
	}

	// --- Events -------------------------------------------------------------

	pi.on("session_start", async (_event, ctx) => {
		currentNn = undefined;
		ensureNn(ctx);
	});

	pi.on("agent_settled", async (_event, ctx) => {
		if (ctx.mode !== "tui") return;
		await tryName(ctx, { force: false });
	});

	// --- Manual command -----------------------------------------------------

	pi.registerCommand("auto-name", {
		description:
			"Generate/refresh the auto session name now (NN - <summary>). Use: /auto-name [reset]",
		handler: async (args, ctx) => {
			const arg = (args || "").trim().toLowerCase();
			if (arg === "reset") {
				// Clear stored named state so it can be regenerated.
				currentNn = currentNn ?? chronologicalIndex(ctx.sessionManager.getSessionDir(), ctx.sessionManager.getSessionFile() ?? "");
				pi.appendEntry(IDX_TYPE, { nn: currentNn, named: false } satisfies StoredIdx);
				ctx.ui.notify(`Reset auto-name (NN=${currentNn}). Regenerating…`, "info");
			}
			const ok = await tryName(ctx, { force: true });
			if (!ok) {
				ctx.ui.notify("Could not auto-name this session (no transcript yet?).", "warn");
			}
		},
	});
}

